import itertools

def count_good_paths(board):
    n = len(board)
    dp = [[0] * n for _ in range(n)]

    # Values in increasing order
    cells = []
    for r in range(n):
        for c in range(n):
            cells.append((board[r][c], r, c))
    cells.sort()

    # dp[r][c] = 1 + sum(dp[nr][nc] for nr, nc in neighbors if board[nr][nc] > board[r][c])
    # We iterate in reverse order of values
    for val, r, c in reversed(cells):
        count = 1
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                if board[nr][nc] > val:
                    count += dp[nr][nc]
        dp[r][c] = count

    total_good_paths = 0
    for r in range(n):
        for c in range(n):
            val = board[r][c]
            is_min = True
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n:
                    if board[nr][nc] < val:
                        is_min = False
                        break
            if is_min:
                total_good_paths += dp[r][c]
    return total_good_paths

def solve_small_n(n):
    min_paths = float('inf')
    nums = list(range(1, n*n + 1))
    for p in itertools.permutations(nums):
        board = [p[i*n : (i+1)*n] for i in range(n)]
        min_paths = min(min_paths, count_good_paths(board))
    return min_paths

