        neighbors = []
        if r > 0: neighbors.append((r-1, c))
        if r < rows - 1: neighbors.append((r+1, c))
        if c > 0: neighbors.append((r, c-1))
        if c < cols - 1: neighbors.append((r, c+1))

        smaller_neighbors = []
        is_local_min = True
        for nr, nc in neighbors:
            if grid[nr][nc] < val:
                is_local_min = False
                smaller_neighbors.append((nr, nc))

        if is_local_min:
            dp[r][c] = 1
