def count_good_paths(board):
    n = len(board)
    dp = [[0] * n for _ in range(n)]
    cells = []
    for r in range(n):
        for c in range(n):
            cells.append((board[r][c], r, c))
    cells.sort()
    for val, r, c in reversed(cells):
        count = 1
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                if board[nr][nc] > val:
                    count += dp[nr][nc]
        dp[r][c] = count
    total_good_paths = 0
    for r in range(n):
        for c in range(n):
            val = board[r][c]
            is_min = True
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n:
                    if board[nr][nc] < val:
                        is_min = False
                        break
            if is_min:
                total_good_paths += dp[r][c]
    return total_good_paths

