def solve_grid(n):
    cells = [(r, c) for r in range(n) for c in range(n)]
    min_s = float('inf')

    for p in itertools.permutations(range(1, n*n + 1)):
        grid = {}
        for i, (r, c) in enumerate(cells):
            grid[(r, c)] = p[i]

        dp = {}
        sources = 0
        for (r, c) in cells:
            val = grid[(r, c)]
            smaller_neighbors = []
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if (nr, nc) in grid and grid[(nr, nc)] < val:
                    smaller_neighbors.append((nr, nc))

            if not smaller_neighbors:
                dp[(r, c)] = 1
                sources += 1
            else:
                dp[(r, c)] = sum(dp[neighbor] for neighbor in smaller_neighbors)

        s = sum(dp.values())
        if s < min_s:
            min_s = s
    return min_s

