import itertools

def solve_small(n):
    grid = [[0]*n for _ in range(n)]
    min_paths = float('inf')

    cells = [(r, c) for r in range(n) for c in range(n)]
    # We can iterate over all permutations of 1..n^2
    # But n^2 = 9, so 9! = 362880.
    for p in itertools.permutations(range(1, n*n + 1)):
        # Fill grid
        for i in range(n*n):
            grid[i // n][i % n] = p[i]

        # Identify local minima
        sources = []
        for r in range(n):
            for c in range(n):
                is_source = True
                for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < n and 0 <= nc < n:
                        if grid[nr][nc] < grid[r][c]:
                            is_source = False
                            break
                if is_source:
                    sources.append((r, c))

        # If more than one source, it's not the minimum (we want 1 source)
        if len(sources) != 1:
            continue

        # Compute P(v)
        P = [[0]*n for _ in range(n)]
        # To compute P(v) in correct order, we can use the fact that 
        # P(v) depends only on neighbors with smaller values.
        # Sort cells by value
        sorted_cells = sorted([(grid[r][c], r, c) for r in range(n) for c in range(n)])

        for val, r, c in sorted_cells:
            if (r, c) in sources:
                P[r][c] = 1
            else:
                res = 0
                for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < n and 0 <= nc < n:
                        if grid[nr][nc] < val:
                            res += P[nr][nc]
                P[r][c] = res

        total_paths = sum(sum(row) for row in P)
        if total_paths < min_paths:
            min_paths = total_paths

    return min_paths

