import math

def nCr(n, r):
    if r < 0 or r > n:
        return 0
    return math.comb(n, r)

def solve_grid_sum(n, r0, c0):
    total = 0
    for r in range(n):
        for c in range(n):
            dr = abs(r - r0)
            dc = abs(c - c0)
            total += nCr(dr + dc, dr)
    return total

