def solve_grid_sum_small(n):
    min_s = float('inf')
    for r0 in range(n):
        for c0 in range(n):
            s = 0
            for r in range(n):
                for c in range(n):
                    dr = abs(r - r0)
                    dc = abs(c - c0)
                    s += math.comb(dr + dc, dr)
            if s < min_s:
