    grid = [[0]*n for _ in range(n)]
    min_paths = float('inf')
    best_grid = None
    best_P = None

    cells = [(r, c) for r in range(n) for c in range(n)]
    for p in itertools.permutations(range(1, n*n + 1)):
        for i in range(n*n):
            grid[i // n][i % n] = p[i]

        sources = []
        for r in range(n):
            for c in range(n):
                is_source = True
                for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < n and 0 <= nc < n:
                        if grid[nr][nc] < grid[r][c]:
                            is_source = False
                            break
                if is_source:
                    sources.append((r, c))

        if len(sources) != 1:
            continue

        P = [[0]*n for _ in range(n)]
        sorted_cells = sorted([(grid[r][c], r, c) for r in range(n) for c in range(n)])
        for val, r, c in sorted_cells:
            if (r, c) in sources:
                P[r][c] = 1
            else:
                res = 0
                for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < n and 0 <= nc < n:
                        if grid[nr][nc] < val:
                            res += P[nr][nc]
                P[r][c] = res

        total_paths = sum(sum(row) for row in P)
        if total_paths < min_paths:
            min_paths = total_paths
            best_grid = [row[:] for row in grid]
            best_P = [row[:] for row in P]

    return min_paths, best_grid, best_P

paths_3, grid_3, P_3 = solve_small_detailed_v32(3)
print(f"n=3: paths={paths_3}")
print(f"best_grid={grid_3}")
print(f"best_P={P_3}")
print(f"Sum of best_P: {sum(sum(row) for row in P_3)}")

