        if len(sources) != 1:
            continue

        P = [[0]*m for _ in range(n)]
        sorted_cells = sorted([(grid[r][c], r, c) for r in range(n) for c in range(m)])
        for val, r, c in sorted_cells:
            if (r, c) in sources:
